const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binaryKeys = Object.keys(item.binary || {});
  if (!binaryKeys.length) throw new Error('No screenshot binary was received. Check the upload form file field.');
  const key = binaryKeys[0];
  const meta = item.binary[key];
  const mimeType = meta.mimeType || 'image/png';
  if (!['image/png', 'image/jpeg', 'image/webp'].includes(mimeType)) {
    throw new Error(`Unsupported image type: ${mimeType}. Upload PNG, JPEG, or WebP.`);
  }
  const buffer = await this.helpers.getBinaryDataBuffer(i, key);
  item.json._firstImage = {
    binaryProperty: 'screenshot',
    fileName: meta.fileName || 'screenshot.png',
    mimeType,
    imageBase64: buffer.toString('base64')
  };
  item.json._allImagesCount = 1;
  item.binary = { screenshot: meta };
  out.push(item);
}
return out;

const item = $input.first();
const response = item.json;
if (response.error) throw new Error('Groq API error (' + (response.error.code || response.error.type || 'unknown') + '): ' + (response.error.message || JSON.stringify(response.error)));
let raw = response.choices?.[0]?.message?.content;
if (typeof raw !== 'string' || !raw.trim()) throw new Error('Groq returned no usable message content. Check the model and API response.');
let report;
try { report = JSON.parse(raw); } catch (e) { throw new Error('Groq response was not valid JSON: ' + e.message); }
for (const key of ['summary', 'description']) {
  if (report[key] === undefined || report[key] === null || String(report[key]).trim() === '') {
    throw new Error(`AI report is missing required field: ${key}`);
  }
}
report.confidence = Number(report.confidence ?? 0);
report.requiresManualReview = Boolean(report.requiresManualReview) || report.confidence < 0.65 || report.isPotentialBug === false;
const original = $('Validate & Encode Screenshot').first();
item.json.aiReport = report;
item.json._screenshotImages = original.json._screenshotImages || [original.json._firstImage];
item.json._firstImage = original.json._firstImage;
item.json.applicationFeature = original.json.applicationFeature || '';
item.json.environment = original.json.environment || 'Unknown';
item.json._jiraDescription = `AI Screenshot Analysis\n\nDescription: ${report.description}\nActual Result: ${report.actualResult || 'Not provided'}\nExpected Result: ${report.expectedResult || 'Not provided'}\nSteps to Reproduce: ${(report.stepsToReproduce || []).join(' | ') || 'Not provided'}\nEvidence: ${(report.evidence || []).join(' | ') || 'See attached screenshot'}\nAssumptions: ${(report.assumptions || []).join(' | ') || 'None stated'}\nMissing Information: ${(report.missingInformation || []).join(' | ') || 'None stated'}\nEnvironment: ${item.json.environment}\nAI confidence: ${report.confidence}\nPotential bug: ${report.isPotentialBug}\nManual review recommended: ${report.requiresManualReview}`;
return [{json: item.json, binary: original.binary}];

