const result = $input.first();
const issue = $('Create Jira Bug').first().json;
const report = $('Validate AI Bug Report').first().json.aiReport;
const base = 'https://YOUR-DOMAIN.atlassian.net';
const issueKey = issue.key;
if (!issueKey) throw new Error('Jira did not return an issue key. Issue creation could not be confirmed.');
const attachmentResponse = result.json;
const attachmentSucceeded = Array.isArray(attachmentResponse) ? attachmentResponse.length > 0 : Boolean(attachmentResponse && !attachmentResponse.error && !attachmentResponse.message?.toLowerCase?.().includes('error'));
return [{json: {status: attachmentSucceeded ? 'created_attachment_response_received' : 'created_but_attachment_needs_review', issueKey, issueUrl: `${base}/browse/${issueKey}`, summary: report.summary, severity: report.severity || 'Unknown', priority: report.priority || 'Unknown', manualReviewRecommended: Boolean(report.requiresManualReview), attachmentFileName: $('Validate & Encode Screenshot').first().json._firstImage?.fileName || 'screenshot', attachmentStatus: attachmentSucceeded ? 'Upload response received; verify attachment in Jira' : 'Attachment may have failed; inspect Jira response and retry against this existing issue', jiraAttachmentResponse: attachmentResponse}}];
